function makeMarker(x,y,z,color,label){const g=new THREE.Group();g.position.set(x,y,z);const ring=new THREE.Mesh(new THREE.TorusGeometry(1.05,.07,8,32),new THREE.MeshBasicMaterial({color,transparent:true,opacity:.9}));ring.rotation.x=Math.PI/2;g.add(ring);const beam=new THREE.Mesh(new THREE.CylinderGeometry(.04,.65,2.7,12,1,true),new THREE.MeshBasicMaterial({color,transparent:true,opacity:.2,side:THREE.DoubleSide}));beam.position.y=1.3;g.add(beam);g.userData={label};scene.add(g);city.push(g);markers.push(g);}
function makeCar(){car=new THREE.Group();scene.add(car);const body=new THREE.Group();car.add(body);carParts=[];const paint=mat(cars[selected].color,.28,.62),dark=mat(0x11151c,.34,.45),glass=new THREE.MeshStandardMaterial({color:0x142a37,roughness:.18,metalness:.5,transparent:true,opacity:.88}),rubber=mat(0x090b0f,.88),rim=mat(0x9aaab0,.23,.85),lampM=new THREE.MeshBasicMaterial({color:0xfff1c4}),tailM=new THREE.MeshBasicMaterial({color:0xff194b});box(body,0,.72,0,2.05,.55,4.35,paint);box(body,0,1.08,-.28,1.7,.72,2.12,glass);box(body,0,.99,-1.7,1.82,.22,1.1,paint);box(body,0,.98,1.75,1.9,.2,.72,paint);box(body,0,.48,-2.16,2.05,.18,.18,dark);box(body,0,.5,2.18,2.15,.22,.2,dark);box(body,-1.04,.74,0,.08,.23,2.6,mat(0xc8d4d8,.3,.7));box(body,1.04,.74,0,.08,.23,2.6,mat(0xc8d4d8,.3,.7));box(body,-.45,1.46,1.47,.12,.58,.12,dark);box(body,.45,1.46,1.47,.12,.58,.12,dark);box(body,0,1.76,1.47,1.1,.12,.17,dark);for(const x of [-.68,.68]){box(body,x,.78,-2.205,.45,.2,.05,lampM);box(body,x,.76,2.205,.48,.18,.05,tailM)}
for(const x of [-1,1])for(const z of [-1.4,1.4]){const wheel=new THREE.Group();wheel.position.set(x,.47,z);const tire=new THREE.Mesh(new THREE.CylinderGeometry(.43,.43,.27,20),rubber);tire.rotation.z=Math.PI/2;wheel.add(tire);const hub=new THREE.Mesh(new THREE.CylinderGeometry(.25,.25,.285,12),rim);hub.rotation.z=Math.PI/2;wheel.add(hub);for(let s=0;s<5;s++){const spoke=new THREE.Mesh(new THREE.BoxGeometry(.035,.38,.045),mat(0xd9e4e6,.25,.8));spoke.position.y=.02;spoke.rotation.z=s*Math.PI/5;hub.add(spoke)}car.add(wheel);wheelMeshes.push(wheel)}
const head=new THREE.SpotLight(0xffedc1,22,44,.48,.38,1.5);head.position.set(-.65,.72,-2.1);head.target.position.set(-.65,0,-12);car.add(head,head.target);const head2=head.clone();head2.position.x=.65;head2.target.position.x=.65;car.add(head2,head2.target);headLights=[head,head2];const glow=new THREE.PointLight(0xff315f,1.3,5);glow.position.set(0,.35,2.15);car.add(glow);car.position.set(0,0,0);}
function updateCarStyle(){const paint=new THREE.Color(cars[selected].color);car.children[0].children.forEach(o=>{if(o.isMesh&&o.material.color&&o.material.color.getHex()!==0x142a37&&o.material.color.getHex()!==0x090b0f&&o.material.color.getHex()!==0x9aaab0&&o.material.color.getHex()!==0xfff1c4&&o.material.color.getHex()!==0xff194b&&o.material.color.getHex()!==0x11151c&&o.material.color.getHex()!==0xc8d4d8){o.material.color.copy(paint)}})}
function resize(){camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(quality==='low'?Math.min(devicePixelRatio,1):quality==='medium'?Math.min(devicePixelRatio,1.35):Math.min(devicePixelRatio,1.7))}
function show(id){$$('.screen').forEach(e=>e.classList.remove('active'));$('#'+id).classList.add('active');$('#hud').style.display=id==='game'&&driving?'block':'none'}
function setCar(i){selected=(i+cars.length)%cars.length;const c=cars[selected];$('#carName').textContent=c.name;$('#carMeta').textContent=c.meta;$('#carDesc').textContent=c.desc;$('#carDots').innerHTML=cars.map((_,n)=>`<span class="dot ${n===selected?'active':''}"></span>`).join('');updateCarStyle()}
function toast(title,detail=''){const el=$('#toast');el.innerHTML=`<b>${title}</b>${detail?`<br>${detail}`:''}`;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2800)}
function beginDrive(){driving=true;started=true;paused=false;car.position.set(-2,0,8);heading=Math.PI;car.rotation.y=heading;speed=0;show('game');$('#touchControls').style.display=touchOn?'block':'none';$('#missionTitle').textContent='Kota ini milikmu';$('#missionText').textContent='Cari ikon neon di sekitar kota. Berkendaralah.';toast('SELAMAT DATANG DI TOKYO','Temui mekanik di ikon cyan • tekan E');}
function enterHome(){driving=false;paused=false;show('home');car.position.set(0,0,0);heading=.65;car.rotation.y=heading}
function setLight(on){lightsOn=on;headLights.forEach(h=>h.intensity=on?22:0);$('#lightBtn').classList.toggle('active',on);$('#touchLight').classList.toggle('active',on)}
function toggleCamera(){cameraMode=(cameraMode+1)%3;const names=['CHASE','COCKPIT','CINEMATIC'];$('#cameraBtn').innerHTML='◫ '+names[cameraMode];$('#touchCamera').textContent='◫ '+names[cameraMode];toast('KAMERA',names[cameraMode])}
function interact(){if(!driving)return;let nearest=null,dist=1e9;markers.forEach(m=>{const d=car.position.distanceTo(m.position);if(d<dist){dist=d;nearest=m}});if(dist>7){toast('BELUM ADA KONTAK','Dekati ikon neon untuk memulai');return}if(nearest.userData.label==='TALK'){task=Math.max(task,1);$('#missionType').textContent='MISI · MEKANIK KENJI';$('#missionTitle').textContent='Paket tengah malam';$('#missionText').textContent='Antarkan suku cadang ke bengkel di ujung blok. Ikuti ikon pink.';markers[0].visible=false;toast('KENJI: "Kau datang tepat waktu."','Misi baru — cari penanda pink')}else if(nearest.userData.label==='DRIFT'){if(task<1){toast('KENJI','Temui aku dulu di dekat bengkel.');return}task=Math.max(task,2);$('#missionType').textContent='MISI · DRIFT CHALLENGE';$('#missionTitle').textContent='Seni di tikungan';$('#missionText').textContent='Tahan handbrake sambil berbelok untuk mengumpulkan 500 poin drift.';markers[2].visible=false;toast('CHALLENGE DIMULAI','Raih 500 poin drift untuk hadiah ¥3,000')}else if(nearest.userData.label==='RACE'){if(task<2){toast('RIVAL: "Pemanasan dulu, bro."','Selesaikan misi drift lebih dulu');return}raceActive=true;raceProgress=0;task=3;$('#missionType').textContent='BALAPAN · SHIBUYA LOOP';$('#missionTitle').textContent='Lawan waktu';$('#missionText').textContent='Lewati 5 checkpoint. Ikuti jalan utama dan tekan gas!';$('#missionProgress').style.width='0%';toast('BALAPAN DIMULAI','Lewati 5 checkpoint di jalanan Shibuya');}}
function completeDrift(){task=3;cash+=3000;$('#cash').textContent=cash.toLocaleString('en-US');$('#missionType').textContent='BALAPAN · SHIBUYA LOOP';$('#missionTitle').textContent='Lawan waktu';$('#missionText').textContent='Temui rival di penanda emas untuk memulai balapan.';markers[1].visible=true;toast('MISI SELESAI','Bonus ¥3,000 · Cari rival di penanda emas')}

