function animate(){requestAnimationFrame(animate);const dt=Math.min(clock.getDelta(),.04),t=clock.elapsedTime;if(!scene)return;markers.forEach(m=>{m.rotation.y=t*.7;m.position.y=1.5+Math.sin(t*2+m.position.x)*.22});if(driving&&!paused){const gas=held.gas||keys.KeyW||keys.ArrowUp,brake=held.brake||keys.KeyS||keys.ArrowDown,left=held.left||keys.KeyA||keys.ArrowLeft,right=held.right||keys.KeyD||keys.ArrowRight,hand=held.handbrake||keys.Space;const c=cars[selected];if(gas)speed+=c.speed*dt*1.65;else if(brake)speed-=c.speed*dt*2.15;else speed*=Math.pow(.985,dt*60);if(hand)speed*=Math.pow(.975,dt*60);speed=THREE.MathUtils.clamp(speed,-9,48);const input=(right?1:0)-(left?1:0);const steerPower=(.28+Math.min(Math.abs(speed)/22,1))*c.turn;heading+=input*steerPower*dt*Math.sign(speed||1);car.rotation.y=heading;const velocityHeading=heading+(hand&&Math.abs(speed)>6?input*.3:0);car.position.x+=Math.sin(velocityHeading)*speed*dt;car.position.z+=Math.cos(velocityHeading)*speed*dt;car.position.x=THREE.MathUtils.clamp(car.position.x,-88,88);car.position.z=THREE.MathUtils.clamp(car.position.z,-88,88);wheelMeshes.forEach((w,i)=>{if(i<2)w.rotation.y=-input*.36;w.children[0].rotation.x+=speed*dt*2.5});const isDrifting=hand&&Math.abs(speed)>7&&Math.abs(input)>.15;drift=isDrifting?drift+Math.abs(speed)*Math.abs(input)*dt*3:Math.max(0,drift-dt*20);const scoreEl=$('#driftScore');scoreEl.classList.toggle('show',isDrifting);scoreEl.querySelector('span').textContent='+'+Math.floor(drift);if(drift>=500&&task===2)completeDrift();if(raceActive){raceProgress+=Math.max(0,speed)*dt/85;$('#missionProgress').style.width=Math.min(100,raceProgress*100)+'%';if(raceProgress>=1){raceActive=false;cash+=5000;$('#cash').textContent=cash.toLocaleString('en-US');$('#missionType').textContent='BALAPAN · SELESAI';$('#missionTitle').textContent='Tokyo tak bisa mengejarmu';$('#missionText').textContent='Kemenanganmu jadi legenda malam ini. Jelajahi kota!';toast('KAMU MENANG!','Bonus balapan ¥5,000');}}const kmh=Math.round(Math.abs(speed)*4.3);$('#speed').textContent=String(kmh).padStart(3,'0');$('#gear').textContent=kmh<2?'N':kmh<40?'2':'3';if(task===1){const d=car.position.distanceTo(markers[2].position);if(d<7)toast('BENGKEL KENJI','Tekan E untuk memulai tantangan drift')}if(task>=4&&!raceActive){const d=car.position.distanceTo(markers[1].position);if(d<8)toast('RIVAL MENUNGGU','Tekan E untuk memulai balapan')}}
// camera follow modes
const forward=new THREE.Vector3(Math.sin(heading),0,Math.cos(heading));let targetPos,targetLook;if(cameraMode===1){targetPos=car.position.clone().add(new THREE.Vector3(0,1.35,0)).addScaledVector(forward,-.1);targetLook=car.position.clone().addScaledVector(forward,18).add(new THREE.Vector3(0,1,0))}else{const back=cameraMode===2?13:9,up=cameraMode===2?6.6:4.7;targetPos=car.position.clone().add(new THREE.Vector3(0,up,0)).addScaledVector(forward,-back);targetLook=car.position.clone().addScaledVector(forward,6).add(new THREE.Vector3(0,1.15,0))}camera.position.lerp(targetPos,1-Math.pow(.001,dt));camera.lookAt(targetLook);camera.fov=THREE.MathUtils.lerp(camera.fov,58+Math.min(Math.abs(speed)*.22,8),.04);camera.updateProjectionMatrix();}else if(paused){camera.lookAt(car.position)}else{camera.position.lerp(new THREE.Vector3(0,5,16),.015);camera.lookAt(0,1,0);camera.position.x=Math.sin(t*.09)*1.1}renderer.render(scene,camera)}

