// UI wiring
$('#playBtn').addEventListener('click',()=>show('garage'));$('#settingsBtn').addEventListener('click',()=>show('settings'));$('#exitBtn').addEventListener('click',()=>{toast('TERIMA KASIH','Sampai jumpa di jalanan Tokyo!')});$$('[data-back]').forEach(b=>b.addEventListener('click',()=>show(b.dataset.back)));$('#driveBtn').addEventListener('click',beginDrive);$('#prevCar').addEventListener('click',()=>setCar(selected-1));$('#nextCar').addEventListener('click',()=>setCar(selected+1));$('#lightSetting').addEventListener('input',e=>{lightLevel=Number(e.target.value)/100;renderer.toneMappingExposure=lightLevel*1.25});$('#volumeSetting').addEventListener('input',e=>volume=Number(e.target.value)/100);$('#qualitySetting').addEventListener('change',e=>{quality=e.target.value;resize()});$('#touchSetting').addEventListener('click',e=>{touchOn=!touchOn;e.currentTarget.classList.toggle('on',touchOn)});$('#lightBtn').addEventListener('click',()=>setLight(!lightsOn));$('#touchLight').addEventListener('click',()=>setLight(!lightsOn));$('#cameraBtn').addEventListener('click',toggleCamera);$('#touchCamera').addEventListener('click',toggleCamera);$('#touchInteract').addEventListener('click',interact);$('#pauseBtn').addEventListener('click',()=>{paused=true;$('#pauseModal').classList.add('show')});$('#resumeBtn').addEventListener('click',()=>{paused=false;$('#pauseModal').classList.remove('show')});$('#garageReturn').addEventListener('click',()=>{ $('#pauseModal').classList.remove('show');enterHome()});window.addEventListener('keydown',e=>{if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();keys[e.code]=true;if(e.repeat)return;if(e.code==='KeyE')interact();if(e.code==='KeyL')setLight(!lightsOn);if(e.code==='KeyC')toggleCamera();if(e.code==='Escape'&&driving){paused=!paused;$('#pauseModal').classList.toggle('show',paused)}});window.addEventListener('keyup',e=>keys[e.code]=false);$$('[data-hold]').forEach(btn=>{const key=btn.dataset.hold;const down=e=>{e.preventDefault();held[key]=true;btn.classList.add('pressed')},up=e=>{e.preventDefault();held[key]=false;btn.classList.remove('pressed')};btn.addEventListener('pointerdown',down);['pointerup','pointercancel','pointerleave'].forEach(ev=>btn.addEventListener(ev,up))});setCar(0);init3D();
